// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.startPrank(alice);
        c.allowance(address(this), alice);
        vm.stopPrank();
        uint256 refWards = c.wards(alice);
        assertTrue(refWards != 0);
    }
}

