pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testRegression_property() public {
        address caller = address(0x1234);
        // Call allowance with a non-authorized caller
        vm.prank(caller);
        c.allowance(address(0), address(0));
        // Check that wards[caller] differs: reference keeps 0, bug sets modifier-passing effect
        assertTrue(c.wards(caller) == 0); // reference: 0; bug: bytes20(caller) != 0 => fails
    }
}

