pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testRegression_property() public {
        address user = address(0x123);
        vm.prank(user);
        c.rely(user);

        // Now try to call updatePrice as a different address that should not be authorized
        address attacker = address(0x456);
        vm.prank(attacker);
        c.updatePrice(100);

        // In the correct contract, attacker is not authorized so latestPrice stays 0.
