contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Set up: call rely with a user different from msg.sender
        address user = address(0x1);
        address caller = address(0x2);
        vm.prank(caller);
        c.rely(user);
        // Now the correct contract has wards[caller] = 0, wards[user] = 1
        // Buggy contract has wards[caller] = 1, wards[user] = 0
        // The allowance function calls share transfer (as proxy) which calls checkTransferRestriction,
        // which is not auth-guarded but the call itself might fail; we check a simpler route:
        // Verify that calling a function with auth modifer (e.g., updatePrice) reverts for caller in correct version
        // but succeeds in buggy version.
        bool ok;
        vm.prank(caller);
        try c.updatePrice(100) { ok = true; } catch { ok = false; }
        // In correct version: revert (ok = false); in buggy: succeed (ok = true)
        // Since we test against the reference (correct), we assert that it reverts (ok = false)
        assertTrue(!ok, "Auth should revert for non-authorized caller");
    }
